import { execFile } from 'child_process';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { promisify } from 'util';
import { createLogger } from '../utils/logger';
import { errorMessage } from '../utils/errorMessage';

const execFileAsync = promisify(execFile);
const log = createLogger('VideoKeyframes');

const FFMPEG_TIMEOUT_MS = 30_000;
const DEFAULT_FRAME_COUNT = 5;

export type KeyframeResult =
  | { ok: true; framePaths: string[] }
  | { ok: false; reason: string };

export const extractVideoKeyframes = async (
  videoPath: string,
  options?: { frameCount?: number; outDir?: string },
): Promise<KeyframeResult> => {
  const frameCount = options?.frameCount ?? DEFAULT_FRAME_COUNT;
  let duration: number;
  try {
    const probe = await execFileAsync(
      'ffprobe',
      [
        '-v',
        'error',
        '-show_entries',
        'format=duration',
        '-of',
        'default=noprint_wrappers=1:nokey=1',
        videoPath,
      ],
      { timeout: FFMPEG_TIMEOUT_MS, env: subprocessEnvironment('verifier') },
    );
    duration = Number.parseFloat(probe.stdout.trim());
    if (!Number.isFinite(duration) || duration <= 0) {
      return { ok: false, reason: `ffprobe reported no duration for ${videoPath}` };
    }
  } catch (error) {
    const message = errorMessage(error);
    return { ok: false, reason: `ffprobe unavailable or failed: ${message}` };
  }

  const outDir =
    options?.outDir ?? fs.mkdtempSync(path.join(os.tmpdir(), 'rivet-keyframes-'));
  const stamps = Array.from(
    { length: frameCount },
    (_, index) => (duration * (index + 0.5)) / frameCount,
  );
  const framePaths: string[] = [];
  try {
    await Promise.all(
      stamps.map(async (stamp, index) => {
        const framePath = path.join(outDir, `frame-${index + 1}.png`);
        await execFileAsync(
          'ffmpeg',
          [
            '-ss',
            stamp.toFixed(2),
            '-i',
            videoPath,
            '-frames:v',
            '1',
            '-q:v',
            '3',
            '-y',
            framePath,
          ],
          { timeout: FFMPEG_TIMEOUT_MS, env: subprocessEnvironment('verifier') },
        );
        framePaths[index] = framePath;
      }),
    );
  } catch (error) {
    const message = errorMessage(error);
    log.warn(`keyframe extraction failed for ${videoPath}`, error);
    return { ok: false, reason: `ffmpeg failed: ${message}` };
  }
  const existing = framePaths.filter(
    (framePath) => framePath && fs.existsSync(framePath),
  );
  if (existing.length === 0) {
    return { ok: false, reason: 'ffmpeg produced no frames' };
  }
  return { ok: true, framePaths: existing };
};
